(55, 'Bông tẩm cồn Bông Bạch Tuyết 6cmx6cm (Hộp 100 miếng)', NULL, 'vtyt-scc-02', '', '', 7, 3, '15000.00', '0.00', 0, '<h3 data-section-id=\"1tz0tp2\" data-start=\"218\" data-end=\"240\" class=\"PDq2pG_selectionAnchorContainer\">Thông tin sản phẩm<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></h3><ul data-start=\"241\" data-end=\"559\">\r\n<li data-section-id=\"1lwxrc0\" data-start=\"241\" data-end=\"290\">\r\n<strong data-start=\"243\" data-end=\"251\">Tên:</strong> Bông tẩm cồn Bông Bạch Tuyết 6cm × 6cm\r\n</li>\r\n<li data-section-id=\"1mjxoht\" data-start=\"291\" data-end=\"325\">\r\n<strong data-start=\"293\" data-end=\"309\">Thương hiệu:</strong> Bông Bạch Tuyết\r\n</li>\r\n<li data-section-id=\"1b5qvf6\" data-start=\"326\" data-end=\"372\">\r\n<strong data-start=\"328\" data-end=\"345\">Nhà sản xuất:</strong> Công Ty CP Bông Bạch Tuyết\r\n</li>\r\n<li data-section-id=\"j6rd94\" data-start=\"373\" data-end=\"402\">\r\n<strong data-start=\"375\" data-end=\"393\">Nước sản xuất:</strong> Việt Nam\r\n</li>\r\n<li data-section-id=\"1eagajo\" data-start=\"403\" data-end=\"432\">\r\n<strong data-start=\"405\" data-end=\"418\">Quy cách:</strong> Hộp 100 miếng\r\n</li>\r\n<li data-section-id=\"1u7d9te\" data-start=\"433\" data-end=\"459\">\r\n<strong data-start=\"435\" data-end=\"450\">Kích thước:</strong> 6 × 6 cm\r\n</li>\r\n<li data-section-id=\"5w3uvj\" data-start=\"460\" data-end=\"484\">\r\n<strong data-start=\"462\" data-end=\"471\">Dạng:</strong> Bông tẩm cồn\r\n</li>\r\n<li data-section-id=\"1rs1t5v\" data-start=\"485\" data-end=\"559\">\r\n<strong data-start=\"487\" data-end=\"502\">Số đăng ký:</strong> 200002250/PCBA-HCM <span class=\"contents\" data-content-reference-start=\"516\" data-content-reference-end=\"547\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"1fj56vo\" data-start=\"561\" data-end=\"573\">Đặc điểm</h3><ul data-start=\"574\" data-end=\"840\">\r\n<li data-section-id=\"4t0dgj\" data-start=\"574\" data-end=\"633\">\r\nBông xơ <strong data-start=\"584\" data-end=\"601\">100% tự nhiên</strong>, xử lý bằng công nghệ Spunlace.\r\n</li>\r\n<li data-section-id=\"18co1fp\" data-start=\"634\" data-end=\"680\">\r\nTẩm <strong data-start=\"640\" data-end=\"655\">Ethanol 70%</strong> theo tiêu chuẩn Bộ Y tế.\r\n</li>\r\n<li data-section-id=\"1s3ys6b\" data-start=\"681\" data-end=\"747\">\r\nThiết kế từng miếng nhỏ, tiện sử dụng trong sơ cứu và sát khuẩn.\r\n</li>\r\n<li data-section-id=\"1ootxhm\" data-start=\"748\" data-end=\"840\">\r\nThành phần: <strong data-start=\"762\" data-end=\"801\">100% bông xơ tự nhiên + Ethanol 70%</strong>. <span class=\"contents\" data-content-reference-start=\"791\" data-content-reference-end=\"823\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"iparcr\" data-start=\"842\" data-end=\"855\">Cách dùng</h3><ul data-start=\"856\" data-end=\"1023\">\r\n<li data-section-id=\"1fz25rm\" data-start=\"856\" data-end=\"928\">\r\nDùng miếng bông lau đều vùng da cần tiêm chích hoặc vật cần khử trùng.\r\n</li>\r\n<li data-section-id=\"1c5dpch\" data-start=\"929\" data-end=\"1023\">\r\n<strong data-start=\"931\" data-end=\"985\">Chỉ dùng ngoài da, sử dụng ngay sau khi mở bao bì.</strong> <span class=\"contents\" data-content-reference-start=\"969\" data-content-reference-end=\"1001\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"7b7utu\" data-start=\"1025\" data-end=\"1034\">Lưu ý</h3><ul data-start=\"1035\" data-end=\"1345\">\r\n<li data-section-id=\"1h3mc3z\" data-start=\"1035\" data-end=\"1097\">\r\nTránh tiếp xúc với mắt; nếu dính mắt, rửa bằng nước/nước ấm.\r\n</li>\r\n<li data-section-id=\"16r0ny\" data-start=\"1098\" data-end=\"1133\">\r\nKhông dùng trên vùng da nhạy cảm.\r\n</li>\r\n<li data-section-id=\"r0xdmv\" data-start=\"1134\" data-end=\"1200\">\r\nKhông dùng cho vết thương sâu, rộng hoặc vùng bỏng nghiêm trọng.\r\n</li>\r\n<li data-section-id=\"1ayyuta\" data-start=\"1201\" data-end=\"1252\">\r\nKhông dùng gần lửa hoặc nguồn có nguy cơ bắt lửa.\r\n</li>\r\n<li data-section-id=\"zesud3\" data-start=\"1253\" data-end=\"1345\">\r\nKhông sử dụng nếu mẫn cảm với bất kỳ thành phần nào. <span class=\"contents\" data-content-reference-start=\"1286\" data-content-reference-end=\"1318\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"ayc2td\" data-start=\"1347\" data-end=\"1359\">Bảo quản</h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1360\" data-end=\"1493\" data-is-last-node=\"\" data-is-only-node=\"\">\r\n<li data-section-id=\"rp1csw\" data-start=\"1360\" data-end=\"1383\">\r\nNơi khô ráo, sạch sẽ.\r\n</li>\r\n<li data-section-id=\"18hgh1u\" data-start=\"1384\" data-end=\"1427\">\r\nTránh nhiệt độ cao và ánh sáng trực tiếp.\r\n</li>\r\n<li data-section-id=\"mbpvaz\" data-start=\"1428\" data-end=\"1493\" data-is-last-node=\"\">\r\nĐể xa tầm với của trẻ em.</li></ul>', 'a1ea734f003814dd5dc4e6fd024d07fc-Bngtmcn6cmx6cmBngBchTuytH100m.jpg', '2026-09-13 20:14:35', 1),
(56, 'Bông tẩm cồn Alcohol Swabs Liworldco (100 miếng) làm sạch và khử trùng da trước khi tiêm', NULL, 'vtyt-scc-03', '', '', 7, 3, '15000.00', '0.00', 0, '<h3 data-section-id=\"1tz0tp2\" data-start=\"270\" data-end=\"292\" class=\"PDq2pG_selectionAnchorContainer\">Thông tin sản phẩm<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></h3><ul data-start=\"293\" data-end=\"624\">\r\n<li data-section-id=\"1ewqlxi\" data-start=\"293\" data-end=\"340\">\r\n<strong data-start=\"295\" data-end=\"303\">Tên:</strong> Bông tẩm cồn Alcohol Swabs Liworldco\r\n</li>\r\n<li data-section-id=\"b5svji\" data-start=\"341\" data-end=\"369\">\r\n<strong data-start=\"343\" data-end=\"359\">Thương hiệu:</strong> Liworldco\r\n</li>\r\n<li data-section-id=\"xrz6il\" data-start=\"370\" data-end=\"399\">\r\n<strong data-start=\"372\" data-end=\"389\">Nhà sản xuất:</strong> LIWORLDCO\r\n</li>\r\n<li data-section-id=\"j6rd94\" data-start=\"400\" data-end=\"429\">\r\n<strong data-start=\"402\" data-end=\"420\">Nước sản xuất:</strong> Việt Nam\r\n</li>\r\n<li data-section-id=\"1eagajo\" data-start=\"430\" data-end=\"459\">\r\n<strong data-start=\"432\" data-end=\"445\">Quy cách:</strong> Hộp 100 miếng\r\n</li>\r\n<li data-section-id=\"10lf3w2\" data-start=\"460\" data-end=\"510\">\r\n<strong data-start=\"462\" data-end=\"477\">Kích thước:</strong> Không được cung cấp trong nguồn.\r\n</li>\r\n<li data-section-id=\"5w3uvj\" data-start=\"511\" data-end=\"535\">\r\n<strong data-start=\"513\" data-end=\"522\">Dạng:</strong> Bông tẩm cồn\r\n</li>\r\n<li data-section-id=\"1jrx9ix\" data-start=\"536\" data-end=\"624\">\r\n<strong data-start=\"538\" data-end=\"553\">Số đăng ký:</strong> Không được cung cấp trong nguồn. <span class=\"contents\" data-content-reference-start=\"580\" data-content-reference-end=\"610\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"1fj56vo\" data-start=\"626\" data-end=\"638\">Đặc điểm</h3><ul data-start=\"639\" data-end=\"1070\">\r\n<li data-section-id=\"xs04bl\" data-start=\"639\" data-end=\"740\">\r\nThành phần: <strong data-start=\"653\" data-end=\"701\">Isopropyl Alcohol 70% (IPA) và bông tự nhiên</strong>. <span class=\"contents\" data-content-reference-start=\"689\" data-content-reference-end=\"719\"></span>\r\n</li>\r\n<li data-section-id=\"8riilh\" data-start=\"741\" data-end=\"791\">\r\nBông tự nhiên mềm mại, thoáng khí, thấm hút tốt.\r\n</li>\r\n<li data-section-id=\"1v0ntbr\" data-start=\"792\" data-end=\"850\">\r\nMỗi miếng được đóng gói riêng, vô trùng và dùng một lần.\r\n</li>\r\n<li data-section-id=\"1tmay7o\" data-start=\"851\" data-end=\"925\">\r\nĐạt tiêu chuẩn <strong data-start=\"868\" data-end=\"886\">ISO 13485:2016</strong>. <span class=\"contents\" data-content-reference-start=\"867\" data-content-reference-end=\"897\"></span>\r\n</li>\r\n<li data-section-id=\"134dxkr\" data-start=\"926\" data-end=\"1070\">\r\nDùng để sát khuẩn da trước khi tiêm, lấy máu hoặc thử đường huyết; có thể vệ sinh một số dụng cụ/bề mặt. <span class=\"contents\" data-content-reference-start=\"1005\" data-content-reference-end=\"1035\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"iparcr\" data-start=\"1072\" data-end=\"1085\">Cách dùng</h3><ul data-start=\"1086\" data-end=\"1197\">\r\n<li data-section-id=\"1de08ef\" data-start=\"1086\" data-end=\"1134\">\r\nLau sạch vùng da cần sát khuẩn trước khi tiêm.\r\n</li>\r\n<li data-section-id=\"1ig4kd7\" data-start=\"1135\" data-end=\"1197\">\r\n<strong data-start=\"1137\" data-end=\"1159\">Chỉ sử dụng 1 lần.</strong> <span class=\"contents\" data-content-reference-start=\"1125\" data-content-reference-end=\"1157\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"7b7utu\" data-start=\"1199\" data-end=\"1208\">Lưu ý</h3><ul data-start=\"1209\" data-end=\"1354\">\r\n<li data-section-id=\"mymx4o\" data-start=\"1209\" data-end=\"1232\">\r\nChỉ sử dụng ngoài da.\r\n</li>\r\n<li data-section-id=\"154brno\" data-start=\"1233\" data-end=\"1252\">\r\nKhông để gần lửa.\r\n</li>\r\n<li data-section-id=\"1hci4uf\" data-start=\"1253\" data-end=\"1295\">\r\nĐọc kỹ hướng dẫn sử dụng trước khi dùng.\r\n</li>\r\n<li data-section-id=\"smy03z\" data-start=\"1296\" data-end=\"1354\">\r\nKhông tái sử dụng. <span class=\"contents\" data-content-reference-start=\"1277\" data-content-reference-end=\"1309\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"ayc2td\" data-start=\"1356\" data-end=\"1368\">Bảo quản</h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1369\" data-end=\"1515\" data-is-last-node=\"\" data-is-only-node=\"\">\r\n<li data-section-id=\"l54590\" data-start=\"1369\" data-end=\"1453\">\r\nBảo quản nơi <strong data-start=\"1384\" data-end=\"1407\">khô ráo, thoáng mát</strong>, tránh các tác nhân ảnh hưởng đến chất lượng.\r\n</li>\r\n<li data-section-id=\"i7wvue\" data-start=\"1454\" data-end=\"1515\" data-is-last-node=\"\">\r\nĐể xa tầm tay trẻ em.</li></ul>', 'fc74e3eaa83a5a30ab0fccf2b096719b-BngTmCnLiworldcoH100M.jpg', '2026-09-13 20:18:42', 1),
(57, 'Bông zigzag Bạch Tuyết 100g vệ sinh cá nhân và y tế', NULL, 'vtyt-scc-24', '', '', 2, 3, '15000.00', '0.00', 0, '<h3 data-section-id=\"1tz0tp2\" data-start=\"223\" data-end=\"245\" class=\"PDq2pG_selectionAnchorContainer\">Thông tin sản phẩm<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></h3><ul data-start=\"246\" data-end=\"601\">\r\n<li data-section-id=\"pff95q\" data-start=\"246\" data-end=\"287\">\r\n<strong data-start=\"248\" data-end=\"256\">Tên:</strong> Bông cắt sẵn Zigzag Bạch Tuyết\r\n</li>\r\n<li data-section-id=\"1yy3f1a\" data-start=\"288\" data-end=\"317\">\r\n<strong data-start=\"290\" data-end=\"306\">Thương hiệu:</strong> Bạch Tuyết\r\n</li>\r\n<li data-section-id=\"37z7oy\" data-start=\"318\" data-end=\"364\">\r\n<strong data-start=\"320\" data-end=\"337\">Nhà sản xuất:</strong> CÔNG TY CP BÔNG BẠCH TUYẾT\r\n</li>\r\n<li data-section-id=\"j6rd94\" data-start=\"365\" data-end=\"394\">\r\n<strong data-start=\"367\" data-end=\"385\">Nước sản xuất:</strong> Việt Nam\r\n</li>\r\n<li data-section-id=\"epz8p9\" data-start=\"395\" data-end=\"419\">\r\n<strong data-start=\"397\" data-end=\"410\">Quy cách:</strong> Gói 100g\r\n</li>\r\n<li data-section-id=\"10lf3w2\" data-start=\"420\" data-end=\"470\">\r\n<strong data-start=\"422\" data-end=\"437\">Kích thước:</strong> Không được cung cấp trong nguồn.\r\n</li>\r\n<li data-section-id=\"788q09\" data-start=\"471\" data-end=\"512\">\r\n<strong data-start=\"473\" data-end=\"482\">Dạng:</strong> Bông y tế cắt sẵn hình Zigzag\r\n</li>\r\n<li data-section-id=\"1jrx9ix\" data-start=\"513\" data-end=\"601\">\r\n<strong data-start=\"515\" data-end=\"530\">Số đăng ký:</strong> Không được cung cấp trong nguồn. <span class=\"contents\" data-content-reference-start=\"559\" data-content-reference-end=\"591\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"1fj56vo\" data-start=\"603\" data-end=\"615\">Đặc điểm</h3><ul data-start=\"616\" data-end=\"1021\">\r\n<li data-section-id=\"1hqtz8j\" data-start=\"616\" data-end=\"677\">\r\n100% bông xơ tự nhiên, không pha polyester, không tạp chất.\r\n</li>\r\n<li data-section-id=\"1bqrkfc\" data-start=\"678\" data-end=\"748\">\r\nCông nghệ <strong data-start=\"690\" data-end=\"702\">Spunlace</strong> giúp bông mềm, chắc, đàn hồi và thấm hút tốt.\r\n</li>\r\n<li data-section-id=\"1fpia27\" data-start=\"749\" data-end=\"821\">\r\nKiểm soát đến 99% xơ thừa trên bề mặt, hạn chế xơ dính vào vết thương.\r\n</li>\r\n<li data-section-id=\"l3qbuv\" data-start=\"822\" data-end=\"929\">\r\nBông được cắt thành từng miếng hình Zigzag, thuận tiện khi sử dụng. <span class=\"contents\" data-content-reference-start=\"882\" data-content-reference-end=\"912\"></span>\r\n</li>\r\n<li data-section-id=\"yfu8bv\" data-start=\"930\" data-end=\"1021\">\r\nĐạt tiêu chuẩn <strong data-start=\"947\" data-end=\"971\">Dược điển Việt Nam V</strong> theo nguồn. <span class=\"contents\" data-content-reference-start=\"967\" data-content-reference-end=\"999\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"iparcr\" data-start=\"1023\" data-end=\"1036\">Cách dùng</h3><ul data-start=\"1037\" data-end=\"1162\">\r\n<li data-section-id=\"6j1oty\" data-start=\"1037\" data-end=\"1049\">\r\nMở bao bì.\r\n</li>\r\n<li data-section-id=\"12ceg1w\" data-start=\"1050\" data-end=\"1073\">\r\nSử dụng theo nhu cầu.\r\n</li>\r\n<li data-section-id=\"uds088\" data-start=\"1074\" data-end=\"1162\">\r\nSau khi sử dụng, bỏ chất thải đúng nơi quy định. <span class=\"contents\" data-content-reference-start=\"1103\" data-content-reference-end=\"1133\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"7b7utu\" data-start=\"1164\" data-end=\"1173\">Lưu ý</h3><ul data-start=\"1174\" data-end=\"1384\">\r\n<li data-section-id=\"1otab9x\" data-start=\"1174\" data-end=\"1206\">\r\nVệ sinh tay trước khi sử dụng.\r\n</li>\r\n<li data-section-id=\"1d2dvkv\" data-start=\"1207\" data-end=\"1260\">\r\nNếu dùng trong điều trị phẫu thuật, cần tiệt trùng.\r\n</li>\r\n<li data-section-id=\"130u0t9\" data-start=\"1261\" data-end=\"1297\">\r\nĐóng kín sản phẩm sau khi sử dụng.\r\n</li>\r\n<li data-section-id=\"1j6qzyw\" data-start=\"1298\" data-end=\"1384\">\r\nTránh khu vực có lửa hoặc nguy cơ bắt lửa cao. <span class=\"contents\" data-content-reference-start=\"1318\" data-content-reference-end=\"1348\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"ayc2td\" data-start=\"1386\" data-end=\"1398\">Bảo quản</h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1399\" data-end=\"1478\" data-is-last-node=\"\" data-is-only-node=\"\">\r\n<li data-section-id=\"f4liya\" data-start=\"1399\" data-end=\"1454\">\r\nBảo quản nơi <strong data-start=\"1414\" data-end=\"1453\">khô ráo, thoáng mát, tránh ánh sáng</strong>.\r\n</li>\r\n<li data-section-id=\"5wkurv\" data-start=\"1455\" data-end=\"1478\" data-is-last-node=\"\">\r\nĐể xa tầm tay trẻ em.</li></ul>', '66961f680594059c9aeff3b1099bdd69-Bngyt100gBchTuyt.jpg', '2026-09-13 20:21:34', 1),
(58, 'Bông thấm nước Bạch Tuyết 25g vệ sinh cá nhân và y tế', NULL, 'vtyt-scc-25', '', '', 2, 3, '15000.00', '0.00', 0, '<h3 data-section-id=\"1tz0tp2\" data-start=\"243\" data-end=\"265\" class=\"PDq2pG_selectionAnchorContainer\">Thông tin sản phẩm<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></h3><ul data-start=\"266\" data-end=\"627\">\r\n<li data-section-id=\"s0q0gk\" data-start=\"266\" data-end=\"335\">\r\n<strong data-start=\"268\" data-end=\"276\">Tên:</strong> Bông cuộn thấm nước Bạch Tuyết 25g vệ sinh cá nhân và y tế\r\n</li>\r\n<li data-section-id=\"1yy3f1a\" data-start=\"336\" data-end=\"365\">\r\n<strong data-start=\"338\" data-end=\"354\">Thương hiệu:</strong> Bạch Tuyết\r\n</li>\r\n<li data-section-id=\"979awi\" data-start=\"366\" data-end=\"401\">\r\n<strong data-start=\"368\" data-end=\"385\">Nhà sản xuất:</strong> BÔNG BẠCH TUYẾT\r\n</li>\r\n<li data-section-id=\"j6rd94\" data-start=\"402\" data-end=\"431\">\r\n<strong data-start=\"404\" data-end=\"422\">Nước sản xuất:</strong> Việt Nam\r\n</li>\r\n<li data-section-id=\"4r1c63\" data-start=\"432\" data-end=\"455\">\r\n<strong data-start=\"434\" data-end=\"447\">Quy cách:</strong> Gói 25g\r\n</li>\r\n<li data-section-id=\"10lf3w2\" data-start=\"456\" data-end=\"506\">\r\n<strong data-start=\"458\" data-end=\"473\">Kích thước:</strong> Không được cung cấp trong nguồn.\r\n</li>\r\n<li data-section-id=\"i6rwn2\" data-start=\"507\" data-end=\"538\">\r\n<strong data-start=\"509\" data-end=\"518\">Dạng:</strong> Bông y tế dạng cuộn\r\n</li>\r\n<li data-section-id=\"1jrx9ix\" data-start=\"539\" data-end=\"627\">\r\n<strong data-start=\"541\" data-end=\"556\">Số đăng ký:</strong> Không được cung cấp trong nguồn. <span class=\"contents\" data-content-reference-start=\"583\" data-content-reference-end=\"615\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"1fj56vo\" data-start=\"629\" data-end=\"641\">Đặc điểm</h3><ul data-start=\"642\" data-end=\"898\">\r\n<li data-section-id=\"b2k8vr\" data-start=\"642\" data-end=\"691\">\r\n100% bông xơ tự nhiên, không pha sợi Polyester.\r\n</li>\r\n<li data-section-id=\"1bbk8r6\" data-start=\"692\" data-end=\"753\">\r\nCông nghệ Spunlace giúp bông mềm, mịn, chắc và đàn hồi tốt.\r\n</li>\r\n<li data-section-id=\"dxpgnp\" data-start=\"754\" data-end=\"814\">\r\nXử lý tới 99% xơ thừa trên bề mặt, tăng hiệu quả thấm hút.\r\n</li>\r\n<li data-section-id=\"uzrsay\" data-start=\"815\" data-end=\"898\">\r\nCó thể dùng trong y tế và chăm sóc cá nhân. <span class=\"contents\" data-content-reference-start=\"849\" data-content-reference-end=\"879\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"iparcr\" data-start=\"900\" data-end=\"913\">Cách dùng</h3><ul data-start=\"914\" data-end=\"1129\">\r\n<li data-section-id=\"1ry72c4\" data-start=\"914\" data-end=\"935\">\r\nMở bao bì sản phẩm.\r\n</li>\r\n<li data-section-id=\"12ceg1w\" data-start=\"936\" data-end=\"959\">\r\nSử dụng theo nhu cầu.\r\n</li>\r\n<li data-section-id=\"11vjxx1\" data-start=\"960\" data-end=\"1010\">\r\nSau khi sử dụng, bỏ chất thải đúng nơi quy định.\r\n</li>\r\n<li data-section-id=\"1i7z5gz\" data-start=\"1011\" data-end=\"1129\">\r\nDùng để sát trùng khi tiêm, lau rửa vết thương, thấm máu và vệ sinh cho em bé. <span class=\"contents\" data-content-reference-start=\"1073\" data-content-reference-end=\"1105\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"7b7utu\" data-start=\"1131\" data-end=\"1140\">Lưu ý</h3><ul data-start=\"1141\" data-end=\"1354\">\r\n<li data-section-id=\"1otab9x\" data-start=\"1141\" data-end=\"1173\">\r\nVệ sinh tay trước khi sử dụng.\r\n</li>\r\n<li data-section-id=\"p4k55b\" data-start=\"1174\" data-end=\"1230\">\r\nKhông sử dụng gần khu vực có lửa hoặc nguy cơ bắt lửa.\r\n</li>\r\n<li data-section-id=\"11lew8k\" data-start=\"1231\" data-end=\"1354\">\r\nKhi dùng cho mục đích đặc biệt, đặc biệt trong sơ cứu, nên tham vấn nhân viên y tế. <span class=\"contents\" data-content-reference-start=\"1293\" data-content-reference-end=\"1325\"></span>\r\n</li>\r\n</ul><h3 data-section-id=\"ayc2td\" data-start=\"1356\" data-end=\"1368\">Bảo quản</h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1369\" data-end=\"1509\" data-is-last-node=\"\" data-is-only-node=\"\">\r\n<li data-section-id=\"yktaez\" data-start=\"1369\" data-end=\"1400\">\r\nNơi khô ráo, đảm bảo vệ sinh.\r\n</li>\r\n<li data-section-id=\"dr9a69\" data-start=\"1401\" data-end=\"1444\">\r\nTránh ánh nắng trực tiếp và nhiệt độ cao.\r\n</li>\r\n<li data-section-id=\"db0rs4\" data-start=\"1445\" data-end=\"1509\" data-is-last-node=\"\">\r\nTránh xa tầm tay trẻ em.&nbsp;</li></ul>', 'ec0aaf1a2cf1939927b1e859d590cc81-Bngyt25gBchTuyt.jpg', '2026-09-13 20:24:00', 1);
